def ul(*items):
    return "<ul>" + "".join(f"<li>{i}</li>" for i in items) + "</ul>"


def a(href, text):
    return f'<a href="{href}">{text}</a>'


def links(*pairs):
    return ul(*[a(h, t) for h, t in pairs if os.path.exists(h) or not h.endswith(".html")])


