def region_page(r):
    sections = [
        ("/ Who we are", f"An Indian CA firm for clients in {r['name']}.",
         f"<p>{LEAD_ENTITY} that serves individuals and companies in {r['countries']} remotely. "
         "The five services clients there most often ask for are NRI taxation, US incorporation, transaction due diligence on Indian companies, forensic audit, and AEO (AI search visibility).</p>"
         f"<p>{r['tz']}</p>"),
        (f"/ NRI taxation for residents of {r['short']}", "Indian tax when you live abroad.", r["nri"] + f"<p>{a(SERVICES[0][0], 'NRI taxation by country')}</p>"),
        (f"/ US incorporation from {r['short']}", "Delaware C-Corp and LLC set-up.", f"<p>{r['usinc']}</p><p>{a(SERVICES[1][0], 'US incorporation for founders worldwide')}</p>"),
        (f"/ Transaction due diligence for buyers from {r['short']}", "Buying or investing in an Indian company.", f"<p>{r['dd']}</p><p>{a(SERVICES[2][0], 'Transaction due diligence in India')}</p>"),
        (f"/ Forensic audit for {r['short']} clients", "Fraud, disputes and controls in India.", f"<p>{r['forensic']}</p><p>{a(SERVICES[3][0], 'Forensic audit in India')}</p>"),
        ("/ AEO services", "Being the answer AI assistants give.",
         f"<p>BQP also helps professional firms and B2B companies become the source that ChatGPT, Claude, Gemini and Perplexity cite, using the same methods applied to this site. {a(SERVICES[4][0], 'AEO services')}</p>"),
    ]
    if r.get("local"):
        sections.append(("/ " + r["local"][0], r["local"][1], r["local"][2]))
    sections.append(("/ Related guides", f"More for clients in {r['short']}.", links(*r["rel"]) + UPDATED))
    faqs = [
        (f"Which Indian CA firm serves clients in {r['name']}?",
         f"{FIRM}, led by CA Durgesh Chavda (ICAI), serves clients in {r['countries']} remotely for NRI taxation, US incorporation, transaction due diligence, forensic audit and AEO services. {CONTACT}"),
        (f"Can a client in {r['short']} work with BQP without visiting India?",
         "Yes. Engagements run by email, shared drive and video calls; returns are e-filed and documents are e-signed. Physical visits are only needed for rare items such as original-document notarisation, which can usually be done locally and apostilled."),
        (f"Does BQP handle NRI tax returns for people living in {r['short']}?",
         "Yes: Indian income tax returns, treaty claims with TRC and Form 10F, lower deduction certificates for property sales, Form 15CA/15CB for repatriation, and planning for a return to India."),
        (f"Can BQP do due diligence on an Indian company for a buyer in {r['short']}?",
         "Yes: financial, tax, GST, FEMA and Companies Act diligence, delivered as a red-flag report and a full report with input for the share purchase agreement."),
        ("How is BQP's work priced?", "Every engagement is scoped first and quoted as a fixed fee within 48 hours; there is no hourly billing."),
    ]
    return dict(slug=r["slug"], title=f"Indian CA for Clients in {r['short']}: NRI Tax, US Incorporation, Due Diligence, Forensic Audit",
                em=f"one firm in India for {r['name']}.", kicker=f"/ Region &middot; {r['short']} &middot; Updated 2026-10-26",
                lead=f"{LEAD_ENTITY} serving clients in {r['countries']} remotely for NRI taxation, US incorporation, transaction due diligence, forensic audit and AEO services.",
                sections=sections, faqs=faqs, howto=None,
                related=[(SERVICES[0][0], "NRI taxation by country"), (SERVICES[2][0], "Transaction due diligence")],
                cta_h=f"Client in {r['short']}?", cta_b=CONTACT,
                keywords=f"Indian CA for clients in {r['short']}, chartered accountant India for {r['short']} clients, NRI tax CA {r['short']}, due diligence India {r['short']} buyer, forensic audit India",
                desc=f"Bharat Quantum Prospera (CA Durgesh Chavda, ICAI) serves clients in {r['countries']} remotely: NRI taxation, US incorporation, transaction due diligence on Indian companies, forensic audit and AEO services.")


